<?php
$statusClass = static fn (string $status): string => $status === 'completed' ? 'badge-success' : ($status === 'cancelled' ? 'badge-secondary' : 'badge-light');
?>
<div class="table-responsive patient-prescriptions-table-wrap"><table class="table patient-prescriptions-table mb-0"><caption class="sr-only">Your prescriptions</caption><thead><tr><th>Prescription</th><th>Doctor</th><th>Date</th><th>Medicines</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach ($prescriptions as $prescription): ?><tr><td data-label="Prescription"><strong class="text-truncate d-block" title="<?= esc($prescription['prescription_number']) ?>"><?= esc($prescription['prescription_number']) ?></strong><small class="text-muted"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i><?= esc($prescription['created_at'] ?? '—') ?></small></td><td data-label="Doctor"><strong class="text-truncate d-block">Dr. <?= esc(trim(($prescription['doctor_first_name'] ?? '') . ' ' . ($prescription['doctor_last_name'] ?? ''))) ?></strong><small class="text-muted d-block text-truncate" title="<?= esc($prescription['specialization'] ?? '') ?>"><?= esc($prescription['specialization'] ?: 'Specialization not recorded') ?></small></td><td data-label="Date"><strong><?= esc($prescription['prescription_date_display']) ?></strong><small class="d-block text-muted">Updated <?= esc($prescription['updated_at'] ?? '—') ?></small></td><td data-label="Medicines"><?= (int) $prescription['medicine_count'] ?> medicine<?= (int) $prescription['medicine_count'] === 1 ? '' : 's' ?></td><td data-label="Status"><span class="badge <?= $statusClass((string) $prescription['status']) ?> patient-status-badge"><?= esc($prescription['status_label']) ?></span></td><td data-label="Actions" class="patient-prescriptions-actions"><div class="dropdown"><button class="btn btn-sm btn-primary dropdown-toggle" type="button" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">More Actions</button><div class="dropdown-menu dropdown-menu-right"><button class="dropdown-item patient-prescription-view" type="button" data-id="<?= (int) $prescription['id'] ?>" data-toggle="modal" data-target="#patient-prescription-detail-modal"><i class="bi bi-eye mr-2" aria-hidden="true"></i>View prescription</button><button class="dropdown-item patient-prescription-print-row" type="button" data-id="<?= (int) $prescription['id'] ?>"><i class="bi bi-printer mr-2" aria-hidden="true"></i>Print</button></div></div></td></tr><?php endforeach; ?>
<?php if ($prescriptions === []): ?><tr><td colspan="6"><div class="patient-empty-state"><i class="bi bi-prescription2" aria-hidden="true"></i><strong>No prescriptions found</strong><span>Try clearing filters.</span></div></td></tr><?php endif; ?></tbody></table></div>
